private theorem ramification_ideal_identity :
    Ideal.map (algebraMap ℤ 𝓞) (Ideal.span {(3 : ℤ)}) =
      cyclotomicPrime a hζ ^ (2 * 3 ^ a)

private theorem coeff_eq_of_hasLeading {n : ℕ} {c : 𝔽₃} {f : Series.PS}
    (h : Series.HasLeading n c f) :
    (∀ i < n, PowerSeries.coeff i f = 0) ∧ PowerSeries.coeff n f = c

theorem sum {ι : Type*} {n : ℕ} (s : Finset ι) {f g : ι → PS}
    (h : ∀ i ∈ s, ModY n (f i) (g i)) :
    ModY n (∑ i ∈ s, f i) (∑ i ∈ s, g i)

private theorem factor_mul_log_term (j : ℕ) :
    (1 + X ^ (j + 1)) *
        (X ^ (j + 1) * (1 + X ^ (j + 1))⁻¹) = X ^ (j + 1)

private theorem tail_two_blocks_second_order {N : ℕ} (hN : ∃ a, N = 3 ^ a) :
    ModY (3 * N) (Tail (2 * N) N)
      (A N * (1 - delta N * L N + delta N ^ 2 * (L N + E N)))

private theorem weight_two_blocks {N b : ℕ} (hN : ∃ a, N = 3 ^ a) :
    ModY (2 * N) (X ^ (2 * N + b + 1))
      (X ^ (b + 1) * (1 - delta N))

private theorem shifted_log_term_first_order {N s j : ℕ} {e : PS}
    (he : Vanishes N e) (hs : X ^ s = 1 + e) :
    ModY (2 * N) (logTerm (s + j)) (logTerm j + e * logSlope j)

private theorem L_three_split (N : ℕ) :
    L (3 * N) = ∑ j ∈ Finset.range N,
      (logTerm j + logTerm (N + j) + logTerm (2 * N + j))

private theorem M_three_split (N : ℕ) :
    M (3 * N) = ∑ j ∈ Finset.range N,
      (logSlope j + logSlope (N + j) + logSlope (2 * N + j))

private theorem L_shift {N s b : ℕ} {e : PS} (he : Vanishes N e)
    (hs : X ^ s = 1 + e) :
    ModY N (L (s + b)) (L s + L b)

private theorem shifted_logSlope {N s j : ℕ} {e : PS} (he : Vanishes N e)
    (hs : X ^ s = 1 + e) :
    ModY N (logSlope (s + j)) (logSlope j)

private theorem M_shift {N s b : ℕ} {e : PS} (he : Vanishes N e)
    (hs : X ^ s = 1 + e) :
    ModY N (M (s + b)) (M s + M b)

private theorem L_shift_precise {N s b : ℕ} {e : PS} (he : Vanishes N e)
    (hs : X ^ s = 1 + e) :
    ModY (2 * N) (L (s + b)) (L s + L b + e * M b)

private theorem F_summand_one_block_coarse {N b : ℕ} (hN : ∃ a, N = 3 ^ a) :
    ModY N (X ^ (N + b + 1) * A (N + b) ^ 2)
      (A N ^ 2 * (X ^ (b + 1) * A b ^ 2))

private theorem F_summand_two_blocks_coarse {N b : ℕ} (hN : ∃ a, N = 3 ^ a) :
    ModY N (X ^ (2 * N + b + 1) * A (2 * N + b) ^ 2)
      (A N ^ 4 * (X ^ (b + 1) * A b ^ 2))

private theorem a_three_sq_exact :
    FinitePolynomial.a 3 ^ 2 - 1 =
      -FinitePolynomial.y ^ 2 + FinitePolynomial.y ^ 3 * qAThree

theorem hasLeading_mul {m n : ℕ} {c d : 𝔽₃} {f g : PS}
    (hf : HasLeading m c f) (hg : HasLeading n d g) :
    HasLeading (m + n) (c * d) (f * g)

theorem hasLeading_pow {n : ℕ} {c : 𝔽₃} {f : PS}
    (h : HasLeading n c f) : ∀ k : ℕ,
    HasLeading (k * n) (c ^ k) (f ^ k)
